//go:build arm64

package floats

// NEON FMA reduction kernels, generated by go-asmgen (kernels_arm64_gen.go) into
// kernels_arm64.s. NEON is part of the ARMv8-A baseline, so there is no runtime
// feature gate — these are used unconditionally on arm64.
func dotNEON(a, b []float64) float64
func sumNEON(a []float64) float64
func sumSqDiffNEON(a, b []float64) float64
func dot32NEON(a, b []float32) float32
func sum32NEON(a []float32) float32
func sumSqDiff32NEON(a, b []float32) float32

func dot(a, b []float64) float64       { return dotNEON(a, b) }
func sum(a []float64) float64          { return sumNEON(a) }
func sumSqDiff(a, b []float64) float64 { return sumSqDiffNEON(a, b) }

func dot32(a, b []float32) float32       { return dot32NEON(a, b) }
func sum32(a []float32) float32          { return sum32NEON(a) }
func sumSqDiff32(a, b []float32) float32 { return sumSqDiff32NEON(a, b) }

// Elementwise float64 updates (kernels_arm64_gen.go): one VFMLA/FMADDD per
// element, bit-identical to math.FMA. The callers pass y (and w) already sliced
// to len(x).
func axpyNEON(alpha float64, x, y []float64)
func xpbyNEON(beta float64, x, y []float64)
func axpyDotNEON(alpha float64, x, y, w []float64) float64
func scaleNEON(alpha float64, x []float64)

// Mul, Axpby3, Clamp and MaxAbs (elem.go): VFMUL / VFMUL+2×VFMLA / FCMGT+BIT /
// FABS+FMAX, each bit-identical to the reference in elem.go. dst, b, c, lo and hi
// are already sliced to the length of the first input.
func mulNEON(dst, a, b []float64)
func axpby3NEON(dst []float64, alpha float64, a []float64, beta float64, b []float64, gamma float64, c []float64)
func clampNEON(dst, v, lo, hi []float64)
func maxAbsNEON(a []float64) float64

func mul(dst, a, b []float64) { mulNEON(dst, a, b) }
func axpby3(dst []float64, alpha float64, a []float64, beta float64, b []float64, gamma float64, c []float64) {
	axpby3NEON(dst, alpha, a, beta, b, gamma, c)
}
func clamp(dst, v, lo, hi []float64) { clampNEON(dst, v, lo, hi) }
func maxAbs(v []float64) float64     { return maxAbsNEON(v) }

func axpy(alpha float64, x, y []float64)               { axpyNEON(alpha, x, y) }
func xpby(beta float64, x, y []float64)                { xpbyNEON(beta, x, y) }
func axpyDot(alpha float64, x, y, w []float64) float64 { return axpyDotNEON(alpha, x, y, w) }
func scale(alpha float64, x []float64)                 { scaleNEON(alpha, x) }
